function abbreviateProduct(left: number, right: number): string {
    let c2 = 0, c5 = 0;
    let logSum = 0;
    let suffix = 1;
    let exact = 1n;
    let big = false;
    const MOD = 100000;
    const LIMIT = 10000000000n;

    for (let i = left; i <= right; i++) {
        let x = i;
        while (x % 2 === 0) { x /= 2; c2++; }
        while (x % 5 === 0) { x /= 5; c5++; }
        logSum += Math.log10(i);
        suffix = (suffix * x) % MOD;
        if (!big) {
            exact *= BigInt(x);
            if (exact >= LIMIT) big = true;
        }
    }

    const C = Math.min(c2, c5);
    for (let k = 0; k < c2 - C; k++) {
        suffix = (suffix * 2) % MOD;
        if (!big) {
            exact *= 2n;
            if (exact >= LIMIT) big = true;
        }
    }
    for (let k = 0; k < c5 - C; k++) {
        suffix = (suffix * 5) % MOD;
        if (!big) {
            exact *= 5n;
            if (exact >= LIMIT) big = true;
        }
    }

    if (!big) {
        return exact.toString() + "e" + C;
    }

    const frac = logSum - Math.floor(logSum);
    let prefix = Math.floor(Math.pow(10, frac + 4));
    if (prefix >= 100000) prefix = 99999;
    if (prefix < 10000) prefix = 10000;

    const suffixStr = suffix.toString().padStart(5, "0");
    return prefix.toString() + "..." + suffixStr + "e" + C;
};
