function ambiguousCoordinates(s: string): string[] {
    const digits = s.substring(1, s.length - 1);
    const n = digits.length;

    const gen = (str: string): string[] => {
        const res: string[] = [];
        const len = str.length;
        if (len === 0) return res;
        if (len === 1 || str[0] !== '0') {
            res.push(str);
        }
        for (let i = 1; i < len; i++) {
            const intPart = str.substring(0, i);
            const fracPart = str.substring(i);
            if (intPart.length > 1 && intPart[0] === '0') continue;
            if (fracPart[fracPart.length - 1] === '0') continue;
            res.push(intPart + "." + fracPart);
        }
        return res;
    };

    const result: string[] = [];
    for (let i = 1; i < n; i++) {
        const left = gen(digits.substring(0, i));
        if (left.length === 0) continue;
        const right = gen(digits.substring(i));
        if (right.length === 0) continue;
        for (const a of left) {
            for (const b of right) {
                result.push("(" + a + ", " + b + ")");
            }
        }
    }
    return result;
};
