inference_trace:
Sort the array, then for each value compute the number of trees rooted at it: 1 (leaf) plus, for every smaller element `a` that divides it with `arr[i]/a` also present, `dp[a] * dp[arr[i]/a]`. Products of dp values can exceed 2^53, so use BigInt for the multiplication step.

```typescript
function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007n;
    const sorted = [...arr].sort((a, b) => a - b);
    const dp = new Map<number, bigint>();
    let total = 0n;
    for (let i = 0; i < sorted.length; i++) {
        const v = sorted[i];
        let count = 1n;
        for (let j = 0; j < i; j++) {
            const a = sorted[j];
            if (a * a > v) break;
            if (v % a === 0) {
                const b = v / a;
                const dpB = dp.get(b);
                if (dpB !== undefined) {
                    const dpA = dp.get(a)!;
                    if (a === b) {
                        count = (count + dpA * dpB) % MOD;
                    } else {
                        count = (count + 2n * dpA * dpB) % MOD;
                    }
                }
            }
        }
        dp.set(v, count);
        total = (total + count) % MOD;
    }
    return Number(total);
};
```

