inference_trace:
Classic reverse union-find approach: remove all hit bricks first, build DSU with a virtual "roof" node, then add bricks back in reverse order, counting how much the roof component grows.

```typescript
function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const g: number[][] = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        if (g[r][c] === 1) {
            g[r][c] = 2; // mark as hit
        }
    }
    const total = m * n;
    const roof = total;
    const parent = new Int32Array(total + 1);
    const size = new Int32Array(total + 1);
    for (let i = 0; i <= total; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a: number, b: number): void => {
        let ra = find(a);
        let rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) {
            const t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    };
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (g[i][j] === 1) {
                const id = i * n + j;
                if (i === 0) union(id, roof);
                if (i + 1 < m && g[i + 1][j] === 1) union(id, (i + 1) * n + j);
                if (j + 1 < n && g[i][j + 1] === 1) union(id, i * n + j + 1);
            }
        }
    }
    const result: number[] = new Array(hits.length).fill(0);
    for (let k = hits.length - 1; k >= 0; k--) {
        const r = hits[k][0];
        const c = hits[k][1];
        if (g[r][c] !== 2) {
            result[k] = 0;
            continue;
        }
        const before = size[find(roof)];
        const id = r * n + c;
        g[r][c] = 1;
        if (r === 0) union(id, roof);
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(id, nr * n + nc);
            }
        }
        const after = size[find(roof)];
        result[k] = Math.max(0, after - before - 1);
    }
    return result;
};
```

