function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const f = (s: string): number => {
        let minC = 'z';
        let cnt = 0;
        for (const ch of s) {
            if (ch < minC) {
                minC = ch;
                cnt = 1;
            } else if (ch === minC) {
                cnt++;
            }
        }
        return cnt;
    };
    // count of words with f value = k, for k in 0..11
    const bucket: number[] = new Array(12).fill(0);
    for (const w of words) {
        bucket[f(w)]++;
    }
    // suffix sums: greater[k] = number of words with f > k
    const greater: number[] = new Array(12).fill(0);
    for (let k = 10; k >= 0; k--) {
        greater[k] = greater[k + 1] + bucket[k + 1];
    }
    const res: number[] = [];
    for (const q of queries) {
        res.push(greater[f(q)]);
    }
    return res;
};
