function countCollisions(directions: string): number {
    let l = 0;
    let r = directions.length - 1;
    while (l <= r && directions[l] === 'L') l++;
    while (r >= l && directions[r] === 'R') r--;
    let count = 0;
    for (let i = l; i <= r; i++) {
        if (directions[i] !== 'S') count++;
    }
    return count;
};
