function countMaxOrSubsets(nums: number[]): number {
    const n = nums.length;
    let maxOr = 0;
    for (const x of nums) maxOr |= x;
    const total = 1 << n;
    const orVal = new Int32Array(total);
    let count = 0;
    for (let mask = 1; mask < total; mask++) {
        const low = mask & (-mask);
        const idx = 31 - Math.clz32(low);
        orVal[mask] = orVal[mask ^ low] | nums[idx];
        if (orVal[mask] === maxOr) count++;
    }
    return count;
};
