function eventualSafeNodes(graph: number[][]): number[] {
    const n = graph.length;
    const outDeg = new Array<number>(n).fill(0);
    const rev: number[][] = Array.from({ length: n }, () => []);
    for (let i = 0; i < n; i++) {
        outDeg[i] = graph[i].length;
        for (const j of graph[i]) {
            rev[j].push(i);
        }
    }
    const queue: number[] = [];
    const safe = new Array<boolean>(n).fill(false);
    for (let i = 0; i < n; i++) {
        if (outDeg[i] === 0) {
            queue.push(i);
            safe[i] = true;
        }
    }
    let head = 0;
    while (head < queue.length) {
        const u = queue[head++];
        for (const v of rev[u]) {
            outDeg[v]--;
            if (outDeg[v] === 0) {
                safe[v] = true;
                queue.push(v);
            }
        }
    }
    const res: number[] = [];
    for (let i = 0; i < n; i++) {
        if (safe[i]) res.push(i);
    }
    return res;
};
