class MKAverage {
    private m: number;
    private k: number;
    private buf: number[];
    private head: number;
    private size: number;
    private cnt: Float64Array;
    private sum: Float64Array;
    private N: number;
    private LOG: number;
    private total: number;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.buf = new Array(m).fill(0);
        this.head = 0;
        this.size = 0;
        this.N = 100001;
        this.cnt = new Float64Array(this.N + 1);
        this.sum = new Float64Array(this.N + 1);
        this.LOG = 1;
        while ((1 << this.LOG) <= this.N) this.LOG++;
        this.total = 0;
    }

    private update(idx: number, dc: number, ds: number): void {
        for (let i = idx; i <= this.N; i += i & (-i)) {
            this.cnt[i] += dc;
            this.sum[i] += ds;
        }
    }

    // sum of smallest t elements
    private sumSmallest(t: number): number {
        if (t <= 0) return 0;
        let pos = 0;
        let remaining = t;
        let s = 0;
        for (let b = this.LOG; b >= 0; b--) {
            const np = pos + (1 << b);
            if (np <= this.N && this.cnt[np] < remaining) {
                pos = np;
                remaining -= this.cnt[np];
                s += this.sum[np];
            }
        }
        // pos+1 is the value where the t-th element lies
        s += remaining * (pos + 1);
        return s;
    }

    addElement(num: number): void {
        if (this.size === this.m) {
            const old = this.buf[this.head];
            this.update(old, -1, -old);
            this.total -= old;
            this.buf[this.head] = num;
            this.head = (this.head + 1) % this.m;
        } else {
            this.buf[(this.head + this.size) % this.m] = num;
            this.size++;
        }
        this.update(num, 1, num);
        this.total += num;
    }

    calculateMKAverage(): number {
        if (this.size < this.m) return -1;
        const low = this.sumSmallest(this.k);
        const upTo = this.sumSmallest(this.m - this.k);
        const mid = upTo - low;
        return Math.floor(mid / (this.m - 2 * this.k));
    }
}

