Classic DP: for each stone index, store the set of jump sizes that can reach it. From stone i with jump k, try k-1, k, k+1 to reach later stones (using a map from position to index). Since the maximum jump size that can reach stone i is at most i, jumps are bounded, so a boolean 2D table works.

```typescript
function canCross(stones: number[]): boolean {
    const n = stones.length;
    if (stones[1] !== 1) return false;
    const pos = new Map<number, number>();
    for (let i = 0; i < n; i++) pos.set(stones[i], i);
    // dp[i] is a Set of jump sizes k such that we can reach stone i with last jump k
    const dp: Set<number>[] = Array.from({ length: n }, () => new Set<number>());
    dp[1].add(1);
    for (let i = 1; i < n; i++) {
        for (const k of dp[i]) {
            for (let d = k - 1; d <= k + 1; d++) {
                if (d <= 0) continue;
                const target = stones[i] + d;
                const j = pos.get(target);
                if (j !== undefined && j > i) {
                    dp[j].add(d);
                }
            }
        }
    }
    return dp[n - 1].size > 0;
};
```

