```typescript
function maxScore(nums: number[]): number {
    const m = nums.length;
    const gcd = (a: number, b: number): number => {
        while (b) { const t = a % b; a = b; b = t; }
        return a;
    };
    const g: number[][] = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            g[i][j] = gcd(nums[i], nums[j]);
        }
    }
    const full = (1 << m) - 1;
    const dp = new Int32Array(1 << m).fill(0);
    // iterate masks from full down to 0; dp[mask] = best score obtainable starting from mask (elements in mask already used)
    for (let mask = full - 1; mask >= 0; mask--) {
        let cnt = 0;
        for (let t = mask; t; t &= t - 1) cnt++;
        if (cnt & 1) continue;
        const op = cnt / 2 + 1;
        let best = 0;
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;
            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;
                const v = dp[mask | (1 << i) | (1 << j)] + op * g[i][j];
                if (v > best) best = v;
            }
        }
        dp[mask] = best;
    }
    return dp[0];
};
