function maximumANDSum(nums: number[], numSlots: number): number {
    const n = nums.length;
    const pow3: number[] = [1];
    for (let i = 1; i <= numSlots; i++) pow3.push(pow3[i - 1] * 3);
    const total = pow3[numSlots];
    const dp = new Int32Array(total).fill(-1);
    dp[0] = 0;
    let best = 0;
    for (let state = 0; state < total; state++) {
        if (dp[state] < 0) continue;
        // count how many numbers placed
        let cnt = 0;
        let s = state;
        for (let i = 0; i < numSlots; i++) {
            cnt += s % 3;
            s = Math.floor(s / 3);
        }
        if (cnt >= n) {
            if (dp[state] > best) best = dp[state];
            continue;
        }
        const val = nums[cnt];
        s = state;
        for (let i = 0; i < numSlots; i++) {
            const d = s % 3;
            s = Math.floor(s / 3);
            if (d < 2) {
                const ns = state + pow3[i];
                const cand = dp[state] + (val & (i + 1));
                if (cand > dp[ns]) dp[ns] = cand;
            }
        }
    }
    return best;
};
