function maximumBinaryString(binary: string): string {
    const n = binary.length;
    let firstZero = -1;
    let zeros = 0;
    for (let i = 0; i < n; i++) {
        if (binary[i] === '0') {
            if (firstZero === -1) firstZero = i;
            zeros++;
        }
    }
    if (zeros <= 1) return binary;
    const arr: string[] = new Array(n).fill('1');
    arr[firstZero + zeros - 1] = '0';
    return arr.join('');
};
