Sliding window approach: for a window [i, j] of fruits, the minimal steps to cover it from startPos is `min(|start - pos[i]|, |start - pos[j]|) + (pos[j] - pos[i])`. Since this cost is monotonic in window expansion, we use a two-pointer sliding window.

```typescript
function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    const n = fruits.length;
    const cost = (l: number, r: number): number => {
        const pl = fruits[l][0], pr = fruits[r][0];
        return (pr - pl) + Math.min(Math.abs(startPos - pl), Math.abs(startPos - pr));
    };
    let left = 0;
    let sum = 0;
    let best = 0;
    for (let right = 0; right < n; right++) {
        sum += fruits[right][1];
        while (left <= right && cost(left, right) > k) {
            sum -= fruits[left][1];
            left++;
        }
        if (left <= right && sum > best) best = sum;
    }
    return best;
};
```

