```typescript
function maxRunTime(n: number, batteries: number[]): number {
    let total = 0;
    for (const b of batteries) total += b;
    let lo = 1;
    let hi = Math.floor(total / n);
    const feasible = (t: number): boolean => {
        let s = 0;
        for (const b of batteries) {
            s += b < t ? b : t;
        }
        return s >= n * t;
    };
    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo + 1) / 2);
        if (feasible(mid)) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    return lo;
};
