Bitmask DP over rows: for each row, enumerate masks that fit in valid seats and have no adjacent bits; transition from previous row masks that don't conflict diagonally.

```typescript
function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    // valid seat mask per row
    const rowMask: number[] = [];
    for (let i = 0; i < m; i++) {
        let mask = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j].trim() === '.') mask |= (1 << j);
        }
        rowMask.push(mask);
    }

    const popcount = (x: number): number => {
        let c = 0;
        while (x) { x &= x - 1; c++; }
        return c;
    };

    // dp[mask] = max students up to current row with current row's mask
    let dp = new Array<number>(full).fill(-1);
    dp[0] = 0;

    for (let i = 0; i < m; i++) {
        const ndp = new Array<number>(full).fill(-1);
        for (let cur = 0; cur < full; cur++) {
            if ((cur & rowMask[i]) !== cur) continue;
            if (cur & (cur << 1)) continue;
            const cnt = popcount(cur);
            for (let prev = 0; prev < full; prev++) {
                if (dp[prev] < 0) continue;
                if (cur & (prev << 1)) continue;
                if (cur & (prev >> 1)) continue;
                const val = dp[prev] + cnt;
                if (val > ndp[cur]) ndp[cur] = val;
            }
        }
        dp = ndp;
    }

    let ans = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] > ans) ans = dp[mask];
    }
    return ans;
};
```

