function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const solve = (L: number, M: number): number => {
        let best = 0;
        let maxL = 0;
        for (let i = L + M; i <= n; i++) {
            // best L-length subarray ending at or before i - M
            const lSum = prefix[i - M] - prefix[i - M - L];
            if (lSum > maxL) maxL = lSum;
            const mSum = prefix[i] - prefix[i - M];
            if (maxL + mSum > best) best = maxL + mSum;
        }
        return best;
    };

    return Math.max(solve(firstLen, secondLen), solve(secondLen, firstLen));
};
