function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const a = flowers.map(v => Math.min(v, target)).sort((x, y) => x - y);
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    const total = prefix[n];
    let best = 0;
    // i = number of incomplete gardens (prefix of length i)
    for (let i = 0; i <= n; i++) {
        if (i > 0 && a[i - 1] >= target) break;
        // cost to complete gardens i..n-1
        const cost = (n - i) * target - (total - prefix[i]);
        if (cost > newFlowers) continue;
        const remaining = newFlowers - cost;
        if (i === 0) {
            best = Math.max(best, n * full);
            continue;
        }
        // find largest p in [1, i] with a[p-1]*p - prefix[p] <= remaining
        let lo = 1, hi = i;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            const c = a[mid - 1] * mid - prefix[mid];
            if (c <= remaining) lo = mid; else hi = mid - 1;
        }
        const p = lo;
        const m = Math.min(target - 1, Math.floor((remaining + prefix[p]) / p));
        const beauty = (n - i) * full + m * partial;
        if (beauty > best) best = beauty;
    }
    return best;
};
