Standard approach: build components of clean (non-initial) nodes with union-find, then for each initial node determine which clean components it touches directly. Components touched by exactly one initial node contribute their size to that node's "saved" count. Pick the node with max saved count, tie-break by smallest index.

```typescript
function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const isInitial: boolean[] = new Array(n).fill(false);
    for (const x of initial) isInitial[x] = true;

    const parent: number[] = new Array(n);
    const size: number[] = new Array(n).fill(1);
    for (let i = 0; i < n; i++) parent[i] = i;

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a: number, b: number): void => {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) { const t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    };

    for (let i = 0; i < n; i++) {
        if (isInitial[i]) continue;
        for (let j = i + 1; j < n; j++) {
            if (isInitial[j]) continue;
            if (graph[i][j] === 1) union(i, j);
        }
    }

    // For each component root, track which initial node touches it (-1 none, -2 multiple)
    const touch: number[] = new Array(n).fill(-1);
    for (const u of initial) {
        const seen = new Set<number>();
        for (let v = 0; v < n; v++) {
            if (isInitial[v] || graph[u][v] === 0) continue;
            const r = find(v);
            if (seen.has(r)) continue;
            seen.add(r);
            if (touch[r] === -1) touch[r] = u;
            else if (touch[r] !== u) touch[r] = -2;
        }
    }

    const saved: number[] = new Array(n).fill(0);
    for (let r = 0; r < n; r++) {
        if (isInitial[r]) continue;
        if (find(r) !== r) continue;
        if (touch[r] >= 0) saved[touch[r]] += size[r];
    }

    const sorted = [...initial].sort((a, b) => a - b);
    let best = sorted[0];
    let bestSaved = -1;
    for (const u of sorted) {
        if (saved[u] > bestSaved) {
            bestSaved = saved[u];
            best = u;
        }
    }
    return best;
};
```

