Classic DP over time: dp[t][v] = min cost to reach v using exactly t minutes. Iterate t from 1 to maxTime, relax all edges. O(maxTime * E).

```typescript
function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const INF = Number.MAX_SAFE_INTEGER;
    // dp[t] = array of min cost to reach each city at exactly time t
    const dp: Int32Array[] = [];
    for (let t = 0; t <= maxTime; t++) {
        const arr = new Int32Array(n);
        arr.fill(0x3f3f3f3f);
        dp.push(arr);
    }
    const BIG = 0x3f3f3f3f;
    dp[0][0] = passingFees[0];
    for (let t = 1; t <= maxTime; t++) {
        const cur = dp[t];
        for (const [x, y, w] of edges) {
            if (w > t) continue;
            const prev = dp[t - w];
            if (prev[x] < BIG) {
                const c = prev[x] + passingFees[y];
                if (c < cur[y]) cur[y] = c;
            }
            if (prev[y] < BIG) {
                const c = prev[y] + passingFees[x];
                if (c < cur[x]) cur[x] = c;
            }
        }
    }
    let ans = BIG;
    for (let t = 0; t <= maxTime; t++) {
        if (dp[t][n - 1] < ans) ans = dp[t][n - 1];
    }
    return ans >= BIG ? -1 : ans;
};
```

