Classic memoized recursion: f(n) = min(n%2 + 1 + f(n/2), n%3 + 1 + f(n/3)), with f(0)=0, f(1)=1.

```typescript
function minDays(n: number): number {
    const memo = new Map<number, number>();
    const f = (x: number): number => {
        if (x <= 1) return x;
        const cached = memo.get(x);
        if (cached !== undefined) return cached;
        const a = (x % 2) + 1 + f(Math.floor(x / 2));
        const b = (x % 3) + 1 + f(Math.floor(x / 3));
        const res = Math.min(a, b);
        memo.set(x, res);
        return res;
    };
    return f(n);
};
```

