Bitmask DP: for each mask, store (sessions, remaining time in current session) as a pair to minimize lexicographically. Iterate subsets, adding one task at a time.

```typescript
function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const full = 1 << n;
    // dp[mask] encoded as sessions * 16 + used time in last session (minimize)
    const INF = Number.MAX_SAFE_INTEGER;
    const dpSess = new Array<number>(full).fill(INF);
    const dpUsed = new Array<number>(full).fill(INF);
    dpSess[0] = 1;
    dpUsed[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dpSess[mask] === INF) continue;
        const s = dpSess[mask];
        const u = dpUsed[mask];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const nm = mask | (1 << i);
            let ns: number, nu: number;
            if (u + tasks[i] <= sessionTime) {
                ns = s;
                nu = u + tasks[i];
            } else {
                ns = s + 1;
                nu = tasks[i];
            }
            if (ns < dpSess[nm] || (ns === dpSess[nm] && nu < dpUsed[nm])) {
                dpSess[nm] = ns;
                dpUsed[nm] = nu;
            }
        }
    }
    return dpSess[full - 1];
};
```

