Classic approach: number of ways = product over nodes of C(left+right, left), then subtract 1. Use Pascal's triangle mod 1e9+7 with n up to 1000, and BigInt-free multiplication via careful modular arithmetic (values < 1e9+7, product may exceed 2^53, so use a safe mulmod).

```typescript
function numOfWays(nums: number[]): number {
    const MOD = 1000000007;
    const n = nums.length;
    // Pascal's triangle
    const C: number[][] = [];
    for (let i = 0; i <= n; i++) {
        C.push(new Array(i + 1).fill(0));
        C[i][0] = 1;
        C[i][i] = 1;
        for (let j = 1; j < i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    const mulmod = (a: number, b: number): number => {
        // a, b < 2^30 roughly; split b to avoid overflow
        const bh = Math.floor(b / 65536);
        const bl = b % 65536;
        const hi = (a * bh) % MOD;
        return ((hi * 65536) % MOD + (a * bl) % MOD) % MOD;
    };

    const count = (arr: number[]): number => {
        if (arr.length <= 2) return 1;
        const root = arr[0];
        const left: number[] = [];
        const right: number[] = [];
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }
        const lw = count(left);
        const rw = count(right);
        const comb = C[left.length + right.length][left.length];
        return mulmod(mulmod(lw, rw), comb);
    };

    const result = count(nums);
    return (result - 1 + MOD) % MOD;
};
```

