Approach: For each value in one array, count pairs in the other array whose product equals its square. Use a frequency map of the other array and for each element a in it, check if square is divisible by a and target b = square/a exists; handle a == b separately. Values up to 1e5 so squares up to 1e10, fine in JS numbers.

```typescript
function numTriplets(nums1: number[], nums2: number[]): number {
    const countFreq = (arr: number[]): Map<number, number> => {
        const m = new Map<number, number>();
        for (const x of arr) m.set(x, (m.get(x) || 0) + 1);
        return m;
    };

    const solve = (a: number[], b: number[]): number => {
        const freqA = countFreq(a);
        const freqB = countFreq(b);
        let total = 0;
        for (const [x, cx] of freqA) {
            const sq = x * x;
            let pairs = 0;
            for (const [y, cy] of freqB) {
                if (sq % y !== 0) continue;
                const z = sq / y;
                if (z === y) {
                    pairs += cy * (cy - 1) / 2;
                } else if (z > y) {
                    const cz = freqB.get(z);
                    if (cz) pairs += cy * cz;
                }
            }
            total += pairs * cx;
        }
        return total;
    };

    return solve(nums1, nums2) + solve(nums2, nums1);
};
```

