```typescript
function maxSizeSlices(slices: number[]): number {
    const m = slices.length;
    const n = m / 3;

    const solve = (arr: number[]): number => {
        const len = arr.length;
        // dp[i][j] = max sum choosing j non-adjacent from first i elements
        const NEG = -Infinity;
        let prev2: number[] = new Array(n + 1).fill(NEG); // dp[i-2]
        let prev1: number[] = new Array(n + 1).fill(NEG); // dp[i-1]
        prev2[0] = 0;
        prev1[0] = 0;
        if (len >= 1) {
            prev1[1] = arr[0];
        }
        for (let i = 2; i <= len; i++) {
            const cur: number[] = new Array(n + 1).fill(NEG);
            cur[0] = 0;
            for (let j = 1; j <= n; j++) {
                const skip = prev1[j];
                const take = prev2[j - 1] === NEG ? NEG : prev2[j - 1] + arr[i - 1];
                cur[j] = Math.max(skip, take);
            }
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1[n];
    };

    if (m === 1) return slices[0];
    const a = solve(slices.slice(1));
    const b = solve(slices.slice(0, m - 1));
    return Math.max(a, b);
};
