function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const parent: number[] = new Array(n * n * 4).fill(0).map((_, i) => i);
    let count = n * n * 4;

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number): void => {
        const ra = find(a);
        const rb = find(b);
        if (ra !== rb) {
            parent[ra] = rb;
            count--;
        }
    };

    const idx = (r: number, c: number, k: number): number => (r * n + c) * 4 + k;

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];
            if (ch === '/') {
                union(idx(r, c, 0), idx(r, c, 3));
                union(idx(r, c, 1), idx(r, c, 2));
            } else if (ch === '\\') {
                union(idx(r, c, 0), idx(r, c, 1));
                union(idx(r, c, 2), idx(r, c, 3));
            } else {
                union(idx(r, c, 0), idx(r, c, 1));
                union(idx(r, c, 1), idx(r, c, 2));
                union(idx(r, c, 2), idx(r, c, 3));
            }
            if (r + 1 < n) {
                union(idx(r, c, 2), idx(r + 1, c, 0));
            }
            if (c + 1 < n) {
                union(idx(r, c, 1), idx(r, c + 1, 3));
            }
        }
    }

    return count;
};
