function removeInvalidParentheses(s: string): string[] {
    let left = 0, right = 0;
    for (const c of s) {
        if (c === '(') left++;
        else if (c === ')') {
            if (left > 0) left--;
            else right++;
        }
    }
    const result: string[] = [];
    const path: string[] = [];
    const n = s.length;

    const dfs = (idx: number, openCount: number, rmLeft: number, rmRight: number): void => {
        if (rmLeft < 0 || rmRight < 0 || openCount < 0) return;
        if (idx === n) {
            if (rmLeft === 0 && rmRight === 0 && openCount === 0) {
                result.push(path.join(''));
            }
            return;
        }
        const c = s[idx];
        if (c === '(' || c === ')') {
            // option: remove this char (only once per run of identical chars)
            if (idx === 0 || s[idx - 1] !== c || (idx > 0 && s[idx - 1] === c && false)) {
                // find run length
            }
            // count run of identical chars
            let j = idx;
            while (j < n && s[j] === c) j++;
            const runLen = j - idx;
            // choose k to remove from this run (0..runLen), keep runLen-k
            for (let k = 0; k <= runLen; k++) {
                const keep = runLen - k;
                if (c === '(') {
                    if (k > rmLeft) break;
                    for (let t = 0; t < keep; t++) path.push(c);
                    dfs(j, openCount + keep, rmLeft - k, rmRight);
                    for (let t = 0; t < keep; t++) path.pop();
                } else {
                    if (k > rmRight) break;
                    if (openCount - keep < 0) continue;
                    for (let t = 0; t < keep; t++) path.push(c);
                    dfs(j, openCount - keep, rmLeft, rmRight - k);
