function medianSlidingWindow(nums: number[], k: number): number[] {
    const n = nums.length;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;
    const idx = new Map<number, number>();
    for (let i = 0; i < m; i++) idx.set(sorted[i], i + 1);
    const tree = new Int32Array(m + 1);
    const add = (i: number, d: number): void => {
        for (; i <= m; i += i & -i) tree[i] += d;
    };
    let LOG = 0;
    while ((1 << (LOG + 1)) <= m) LOG++;
    const kth = (r: number): number => {
        let pos = 0;
        for (let b = LOG; b >= 0; b--) {
            const np = pos + (1 << b);
            if (np <= m && tree[np] < r) {
                pos = np;
                r -= tree[np];
            }
        }
        return sorted[pos];
    };
    const res: number[] = [];
    for (let i = 0; i < k; i++) add(idx.get(nums[i])!, 1);
    const odd = (k & 1) === 1;
    for (let i = k; ; i++) {
        if (odd) {
            res.push(kth((k + 1) >> 1));
        } else {
            const a = kth(k >> 1);
            const b = kth((k >> 1) + 1);
            res.push((a + b) / 2);
        }
        if (i >= n) break;
        add(idx.get(nums[i])!, 1);
        add(idx.get(nums[i - k])!, -1);
    }
    return res;
};
