            const [dr, dc] = dirs[d];
            for (let s = 0; s < step; s++) {
                r += dr;
                c += dc;
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    result.push([r, c]);
                    if (result.length === total) return result;
                }
            }
            d = (d + 1) % 4;
        }
        step++;
    }
    return result;
};
