function splitArray(nums: number[], k: number): number {
    let lo = 0;
    let hi = 0;
    for (const x of nums) {
        lo = Math.max(lo, x);
        hi += x;
    }

    const canSplit = (limit: number): boolean => {
        let count = 1;
        let cur = 0;
        for (const x of nums) {
            if (cur + x > limit) {
                count++;
                cur = x;
                if (count > k) return false;
            } else {
                cur += x;
            }
        }
        return true;
    };

    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (canSplit(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
};
