inference_trace:
Classic bitmask DP over subsets of target characters: for each mask (set of covered target positions), try each sticker and greedily fill uncovered positions with letters from that sticker; BFS/DP over masks.

```typescript
function minStickers(stickers: string[], target: string): number {
    const m = target.length;
    const full = (1 << m) - 1;
    const stickerCounts: number[][] = stickers.map(s => {
        const c = new Array(26).fill(0);
        for (const ch of s) c[ch.charCodeAt(0) - 97]++;
        return c;
    });
    const targetCodes: number[] = [];
    for (let i = 0; i < m; i++) targetCodes.push(target.charCodeAt(i) - 97);

    const dp = new Array<number>(1 << m).fill(-1);
    dp[0] = 0;
    for (let mask = 0; mask <= full; mask++) {
        if (dp[mask] < 0) continue;
        for (const cnt of stickerCounts) {
            const c = cnt.slice();
            let next = mask;
            for (let i = 0; i < m; i++) {
                if ((next & (1 << i)) === 0 && c[targetCodes[i]] > 0) {
                    c[targetCodes[i]]--;
                    next |= 1 << i;
                }
            }
            if (next === mask) continue;
            if (dp[next] < 0 || dp[next] > dp[mask] + 1) {
                dp[next] = dp[mask] + 1;
            }
        }
    }
    return dp[full];
};
```

