class StreamChecker {
    private children: Int32Array[];
    private terminal: boolean[];
    private stream: number[];
    private maxLen: number;

    constructor(words: string[]) {
        this.children = [new Int32Array(26).fill(-1)];
        this.terminal = [false];
        this.stream = [];
        this.maxLen = 0;
        for (const w of words) {
            if (w.length > this.maxLen) this.maxLen = w.length;
            let node = 0;
            for (let i = w.length - 1; i >= 0; i--) {
                const c = w.charCodeAt(i) - 97;
                if (this.children[node][c] === -1) {
                    this.children[node][c] = this.children.length;
                    this.children.push(new Int32Array(26).fill(-1));
                    this.terminal.push(false);
                }
                node = this.children[node][c];
            }
            this.terminal[node] = true;
        }
    }

    query(letter: string): boolean {
        this.stream.push(letter.charCodeAt(0) - 97);
        if (this.stream.length > this.maxLen) {
            this.stream.shift();
        }
        let node = 0;
        for (let i = this.stream.length - 1; i >= 0; i--) {
            node = this.children[node][this.stream[i]];
            if (node === -1) return false;
            if (this.terminal[node]) return true;
        }
        return false;
    }
}

