function sumOddLengthSubarrays(arr: number[]): number {
    const n = arr.length;
    let sum = 0;
    for (let i = 0; i < n; i++) {
        const total = (i + 1) * (n - i);
        const odd = Math.floor((total + 1) / 2);
        sum += arr[i] * odd;
    }
    return sum;
};
