function kWeakestRows(mat: number[][], k: number): number[] {
    const m = mat.length;
    const n = mat[0].length;
    const counts: number[] = new Array(m);
    for (let i = 0; i < m; i++) {
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (mat[i][mid] === 1) lo = mid + 1;
            else hi = mid;
        }
        counts[i] = lo;
    }
    const idx: number[] = [];
    for (let i = 0; i < m; i++) idx.push(i);
    idx.sort((a, b) => counts[a] !== counts[b] ? counts[a] - counts[b] : a - b);
    return idx.slice(0, k);
};
