Classic approach: DFS with, for each value 1..50, a stack of (node, depth) of ancestors having that value. For each node, check all coprime values, pick the ancestor with max depth. Use iterative DFS to avoid stack overflow.

```typescript
function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const adj: number[][] = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const gcd = (a: number, b: number): number => {
        while (b) { const t = a % b; a = b; b = t; }
        return a;
    };
    const coprimes: number[][] = Array.from({ length: 51 }, () => []);
    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            if (gcd(a, b) === 1) coprimes[a].push(b);
        }
    }
    // stacks per value: store node and depth
    const stackNode: number[][] = Array.from({ length: 51 }, () => []);
    const stackDepth: number[][] = Array.from({ length: 51 }, () => []);
    const ans: number[] = new Array(n).fill(-1);
    const depth: number[] = new Array(n).fill(0);
    const parent: number[] = new Array(n).fill(-1);
    const idx: number[] = new Array(n).fill(0);

    // iterative DFS
    const stack: number[] = [0];
    // process entering node 0
    const enter = (node: number) => {
        const v = nums[node];
        let bestDepth = -1;
        let best = -1;
        for (const c of coprimes[v]) {
            const sn = stackNode[c];
            if (sn.length > 0) {
                const d = stackDepth[c][sn.length - 1];
                if (d > bestDepth) {
                    bestDepth = d;
                    best = sn[sn.length - 1];
                }
            }
        }
        ans[node] = best;
        stackNode[v].push(node);
        stackDepth[v].push(depth[node]);
    };
    const exit = (node: number) => {
        const v = nums[node];
        stackNode[v].pop();
        stackDepth[v].pop();
    };

    enter(0);
    while (stack.length > 0) {
        const node = stack[stack.length - 1];
        if (idx[node] < adj[node].length) {
            const nxt = adj[node][idx[node]++];
            if (nxt === parent[node]) continue;
            parent[nxt] = node;
            depth[nxt] = depth[node] + 1;
            enter(nxt);
            stack.push(nxt);
        } else {
            exit(node);
            stack.pop();
        }
    }
    return ans;
};
