Compute indegrees; each node must have indegree ≤ 1, exactly one root with indegree 0, then BFS/DFS from the root and verify all n nodes are reached (which rules out cycles and disconnected components).

```typescript
function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const indeg = new Array<number>(n).fill(0);
    for (let i = 0; i < n; i++) {
        const l = leftChild[i], r = rightChild[i];
        if (l !== -1) {
            if (++indeg[l] > 1) return false;
        }
        if (r !== -1) {
            if (++indeg[r] > 1) return false;
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const visited = new Array<boolean>(n).fill(false);
    const stack: number[] = [root];
    visited[root] = true;
    let count = 0;
    while (stack.length > 0) {
        const node = stack.pop()!;
        count++;
        const l = leftChild[node], r = rightChild[node];
        if (l !== -1) {
            if (visited[l]) return false;
            visited[l] = true;
            stack.push(l);
        }
        if (r !== -1) {
            if (visited[r]) return false;
            visited[r] = true;
            stack.push(r);
        }
    }
    return count === n;
};
```

