function isSolvable(words: string[], result: string): boolean {
    for (const w of words) {
        if (w.length > result.length) return false;
    }
    const weight: Map<string, number> = new Map();
    const nonzero: Set<string> = new Set();
    const addWord = (w: string, sign: number) => {
        let p = 1;
        for (let i = w.length - 1; i >= 0; i--) {
            const c = w[i];
            weight.set(c, (weight.get(c) || 0) + sign * p);
            p *= 10;
        }
        if (w.length > 1) nonzero.add(w[0]);
    };
    for (const w of words) addWord(w, 1);
    addWord(result, -1);

    const chars = Array.from(weight.keys());
    chars.sort((a, b) => Math.abs(weight.get(b)!) - Math.abs(weight.get(a)!));
    const n = chars.length;
    const ws: number[] = chars.map(c => weight.get(c)!);
    const nz: boolean[] = chars.map(c => nonzero.has(c));

    const maxRem: number[] = new Array(n + 1).fill(0);
    const minRem: number[] = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        maxRem[i] = maxRem[i + 1] + (ws[i] > 0 ? 9 * ws[i] : 0);
        minRem[i] = minRem[i + 1] + (ws[i] < 0 ? 9 * ws[i] : 0);
    }

    const dfs = (idx: number, sum: number, used: number): boolean => {
        if (idx === n) return sum === 0;
        if (sum + minRem[idx] > 0 || sum + maxRem[idx] < 0) return false;
        for (let d = 0; d <= 9; d++) {
            if (used & (1 << d)) continue;
            if (d === 0 && nz[idx]) continue;
            if (dfs(idx + 1, sum + ws[idx] * d, used | (1 << d))) return true;
        }
        return false;
    };

    return dfs(0, 0, 0);
};
