Greedy two-pointer approach with backtracking to the last `*`.

```typescript
function isMatch(s: string, p: string): boolean {
    let i = 0, j = 0;
    let starIdx = -1, matchIdx = 0;
    const n = s.length, m = p.length;
    while (i < n) {
        if (j < m && (p[j] === '?' || p[j] === s[i])) {
            i++;
            j++;
        } else if (j < m && p[j] === '*') {
            starIdx = j;
            matchIdx = i;
            j++;
        } else if (starIdx !== -1) {
            j = starIdx + 1;
            matchIdx++;
            i = matchIdx;
        } else {
            return false;
        }
    }
    while (j < m && p[j] === '*') {
        j++;
    }
    return j === m;
};
```

